"    # Actions: Click, Fill, Select, Hover, Scroll
    # ------------------------------------------------------------------

    async def click(self, ref: str) -> str:
        """Click an element by @eN reference or pruned index."""
        if ref.isdigit():
            idx = int(ref)
            target = next((el for el in self._pruned_elements if el['index'] == idx), None)
            if not target:
                return f"Error: Pruned element [{idx}] not found."
            cx, cy = target['center']
            try:
                await self.page.mouse.click(cx, cy)
                return f"Clicked pruned element [{idx}] at ({cx:.0f}, {cy:.0f})"
            except Exception as e:
                return f"Error clicking [{idx}]: {str(e)}"

        entry = await self._resolve_ref(ref)
        if not entry:
            return f"Error: Could not resolve reference {ref}"

        center = await self._get_element_center(entry)
        if not center:
            # Fallback: JS click
